package com.zad.almoslem;
import android.app.Activity;import android.content.SharedPreferences;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.view.Gravity;import android.view.View;import android.widget.*;
public class TasbeehActivity extends Activity{
String[] dhikr={"سبحان الله","الحمد لله","الله أكبر","لا إله إلا الله","أستغفر الله وأتوب إليه","اللهم صلِّ وسلم على نبينا محمد"};SharedPreferences prefs;int count,goal,index;TextView number,phrase,progress,target;
int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}GradientDrawable bg(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
TextView label(String s,int z,int c,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.CENTER);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
@Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("zad_reminders",MODE_PRIVATE);goal=prefs.getInt("native_tasbeeh_goal",33);count=prefs.getInt("native_tasbeeh_count",0);index=Math.floorMod(prefs.getInt("native_tasbeeh_dhikr",0),dhikr.length);getWindow().setStatusBarColor(Color.rgb(8,48,40));getWindow().setNavigationBarColor(Color.rgb(8,48,40));build();}
void build(){ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER_HORIZONTAL);root.setPadding(dp(18),dp(18),dp(18),dp(24));root.setBackgroundColor(Color.rgb(244,247,243));scroll.addView(root);root.addView(label("السبحة الإلكترونية",24,Color.rgb(8,48,40),true));TextView sub=label("وَاذْكُرُوا اللَّهَ كَثِيرًا",15,Color.rgb(158,124,53),true);sub.setPadding(0,dp(5),0,dp(16));root.addView(sub);
LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setGravity(Gravity.CENTER);card.setPadding(dp(16),dp(18),dp(16),dp(18));card.setBackground(bg(Color.rgb(17,65,51),24));root.addView(card,new LinearLayout.LayoutParams(-1,-2));phrase=label("",21,Color.WHITE,true);phrase.setPadding(0,dp(8),0,dp(14));card.addView(phrase);
FrameLayout ring=new FrameLayout(this);GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor(Color.rgb(10,49,40));circle.setStroke(dp(3),Color.rgb(218,185,112));ring.setBackground(circle);number=label("",40,Color.rgb(232,203,137),true);ring.addView(number,new FrameLayout.LayoutParams(dp(132),dp(132),Gravity.CENTER));LinearLayout holder=new LinearLayout(this);holder.setGravity(Gravity.CENTER);holder.addView(ring,new LinearLayout.LayoutParams(dp(144),dp(144)));card.addView(holder);target=label("",14,Color.rgb(240,237,220),false);target.setPadding(0,dp(12),0,dp(3));card.addView(target);progress=label("",12,Color.rgb(220,220,210),false);card.addView(progress);
root.addView(label("اختر عدد التسبيحات",15,Color.rgb(35,60,47),true));Spinner picker=new Spinner(this);picker.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"٣٣ مرة","٦٦ مرة","٩٩ مرة"}));picker.setSelection(goal==66?1:goal==99?2:0);root.addView(picker);picker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){int g=new int[]{33,66,99}[pos];if(goal!=g){goal=g;count=0;save();}render();}});
Button add=new Button(this);add.setText("سَبِّح");add.setTextSize(18);add.setTextColor(Color.WHITE);add.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(17,91,68)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(58));lp.topMargin=dp(18);root.addView(add,lp);add.setOnClickListener(v->{count++;if(count>=goal){count=0;index=(index+1)%dhikr.length;Toast.makeText(this,"أحسنت، اكتمل الذكر. انتقلنا إلى الذكر التالي",Toast.LENGTH_SHORT).show();}save();render();});
Button reset=new Button(this);reset.setText("إعادة ضبط الذكر الحالي");root.addView(reset);reset.setOnClickListener(v->{count=0;save();render();});setContentView(AppTabs.wrap(this,scroll,"tasbeeh"));render();}
void save(){prefs.edit().putInt("native_tasbeeh_goal",goal).putInt("native_tasbeeh_count",count).putInt("native_tasbeeh_dhikr",index).apply();}
void render(){phrase.setText(dhikr[index]);number.setText(String.valueOf(count));target.setText("الهدف: "+goal+" مرة");progress.setText("الذكر "+(index+1)+" من "+dhikr.length+" • "+count+" / "+goal);}
}